contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        uint256 ownerBalanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(ownerBalanceBefore >= amount);
        c.burn(amount); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalSupplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(ownerBalanceAfter == ownerBalanceBefore - amount && totalSupplyAfter == totalSupplyBefore - amount);
    }
}

