        try c.totalSupply() returns (uint256 __r) { totalSupplyBefore = __r; } catch { return; }
        vm.assume(ownerBalanceBefore >= amount);
        try c.burn(amount) {} catch { return; }
        uint256 ownerBalanceAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { ownerBalanceAfter = __r; } catch { return; }
